def build_block(locale, data):
    lines = ["      svcdesc: {"]
    for group, items in data.items():
        lines.append("        %s: {" % group)
        for key, val in items.items():
            lines.append("          %s: \"%s\"," % (key, val.replace('"', '\\"')))
        lines.append("        },")
    lines.append("      },")
    return "\n".join(lines) + "\n"


